WITH flattened_attrs AS (SELECT id, created_at, coupon_codes, ship_to, attributes, ship_to.country AS ship_country, ARRAY_CONTAINS(coupon_codes, 'SPRING10') AS used_spring10 FROM carts WHERE TO_DATE(created_at) < '2025-08-10') SELECT *, FIRST_VALUE(ship_country, TRUE) OVER w_recent AS first_known_ship_country, LAST_VALUE(ship_country, TRUE) OVER w_recent AS last_known_ship_country, ROW_NUMBER() OVER (PARTITION BY ship_country ORDER BY created_at DESC, id) AS row_seq FROM flattened_attrs WINDOW w_recent AS (PARTITION BY ship_country ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
